lleries\"]', '{\"PKR\":[\"No preference\",\"Less than PKR 50,000\",\"PKR 50,000 – PKR 100,000\",\"PKR 100,000 – PKR 200,000\",\"PKR 200,000 – PKR 600,000\",\"PKR 600,000 – PKR 1,000,000\",\"PKR 1,000,000+\"],\"AED\":[\"No preference\",\"Less than AED 2,000\",\"AED 2,000 – AED 5,000\",\"AED 5,000 – AED 10,000\",\"AED 10,000 – AED 20,000\",\"AED 20,000 – AED 50,000\",\"AED 50,000+\"],\"SAR\":[\"No preference\",\"Less than SAR 3,000\",\"SAR 3,000 – SAR 6,000\",\"SAR 6,000 – SAR 12,000\",\"SAR 12,000 – SAR 25,000\",\"SAR 25,000 – SAR 50,000\",\"SAR 50,000+\"],\"QAR\":[\"No preference\",\"Less than QAR 3,000\",\"QAR 3,000 – QAR 6,000\",\"QAR 6,000 – QAR 12,000\",\"QAR 12,000 – QAR 25,000\",\"QAR 25,000 – QAR 50,000\",\"QAR 50,000+\"],\"BHD\":[\"No preference\",\"Less than BHD 300\",\"BHD 300 – BHD 700\",\"BHD 700 – BHD 1,500\",\"BHD 1,500 – BHD 3,000\",\"BHD 3,000 – BHD 6,000\",\"BHD 6,000+\"],\"KWD\":[\"No preference\",\"Less than KWD 200\",\"KWD 200 – KWD 500\",\"KWD 500 – KWD 1,000\",\"KWD 1,000 – KWD 2,000\",\"KWD 2,000 – KWD 5,000\",\"KWD 5,000+\"],\"OMR\":[\"No preference\",\"Less than OMR 300\",\"OMR 300 – OMR 700\",\"OMR 700 – OMR 1,500\",\"OMR 1,500 – OMR 3,000\",\"OMR 3,000 – OMR 6,000\",\"OMR 6,000+\"],\"USD\":[\"No preference\",\"Less than $2,000\",\"$2,000 – $5,000\",\"$5,000 – $10,000\",\"$10,000 – $20,000\",\"$20,000 – $50,000\",\"$50,000+\"],\"GBP\":[\"No preference\",\"Less than £2,000\",\"£2,000 – £4,000\",\"£4,000 – £8,000\",\"£8,000 – £15,000\",\"£15,000 – £30,000\",\"£30,000+\"],\"CAD\":[\"No preference\",\"Less than CAD 2,000\",\"CAD 2,000 – CAD 4,000\",\"CAD 4,000 – CAD 7,000\",\"CAD 7,000 – CAD 12,000\",\"CAD 12,000 – CAD 25,000\",\"CAD 25,000+\"],\"AUD\":[\"No preference\",\"Less than AUD 3,000\",\"AUD 3,000 – AUD 5,000\",\"AUD 5,000 – AUD 8,000\",\"AUD 8,000 – AUD 15,000\",\"AUD 15,000 – AUD 30,000\",\"AUD 30,000+\"],\"EUR\":[\"No preference\",\"Less than €1,500\",\"€1,500 – €3,000\",\"€3,000 – €5,000\",\"€5,000 – €8,000\",\"€8,000 – €15,000\",\"€15,000+\"],\"NOK\":[\"No preference\",\"Less than NOK 20,000\",\"NOK 20,000 – NOK 40,000\",\"NOK 40,000 – NOK 70,000\",\"NOK 70,000 – NOK 120,000\",\"NOK 120,000 – NOK 200,000\",\"NOK 200,000+\"],\"SEK\":[\"No preference\",\"Less than SEK 20,000\",\"SEK 20,000 – SEK 35,000\",\"SEK 35,000 – SEK 60,000\",\"SEK 60,000 – SEK 100,000\",\"SEK 100,000 – SEK 200,000\",\"SEK 200,000+\"],\"DKK\":[\"No preference\",\"Less than DKK 15,000\",\"DKK 15,000 – DKK 30,000\",\"DKK 30,000 – DKK 50,000\",\"DKK 50,000 – DKK 80,000\",\"DKK 80,000 – DKK 150,000\",\"DKK 150,000+\"],\"CHF\":[\"No preference\",\"Less than CHF 3,000\",\"CHF 3,000 – CHF 5,000\",\"CHF 5,000 – CHF 8,000\",\"CHF 8,000 – CHF 12,000\",\"CHF 12,000 – CHF 20,000\",\"CHF 20,000+\"],\"TRY\":[\"No preference\",\"Less than TRY 10,000\",\"TRY 10,000 – TRY 25,000\",\"TRY 25,000 – TRY 50,000\",\"TRY 50,000 – TRY 100,000\",\"TRY 100,000 – TRY 250,000\",\"TRY 250,000+\"],\"MYR\":[\"No preference\",\"Less than MYR 2,000\",\"MYR 2,000 – MYR 4,000\",\"MYR 4,000 – MYR 8,000\",\"MYR 8,000 – MYR 15,000\",\"MYR 15,000 – MYR 30,000\",\"MYR 30,000+\"],\"NZD\":[\"No preference\",\"Less than NZD 2,500\",\"NZD 2,500 – NZD 5,000\",\"NZD 5,000 – NZD 8,000\",\"NZD 8,000 – NZD 15,000\",\"NZD 15,000 – NZD 30,000\",\"NZD 30,000+\"]}', '{\"muslim\":[\"We are a religious family with strong values, rooted in our cultural traditions and faith.\",\"A close-knit family with educated parents. We value deen, respect, and simplicity.\",\"Middle-class family with strong Islamic values. Parents are both educated professionals.\",\"Conservative Muslim family with roots in Pakistan. We believe in maintaining family ties.\",\"A warm and welcoming family. We prioritise faith, education and character above all.\",\"Well-established family with a strong emphasis on religious education and community service.\",\"Our family is deeply rooted in Islamic values. We are respectful, humble and family-oriented.\",\"A peaceful and loving home. My parents raised us with the Quran and strong moral character.\",\"We come from a respected background, placing high importance on deen and integrity.\",\"A modest and practising Muslim family. We believe in simplicity, honesty and hard work.\",\"Alhamdulillah, we are a blessed family. Faith and family are at the heart of who we are.\",\"A family of scholars and professionals, united by love for deen and each other.\",\"We follow traditional Islamic values whilst embracing education and modern life.\",\"Our household is built on salah, sabr and shukr. We are looking for someone who shares our values.\",\"A humble Pakistani family with roots in the homeland and branches across the world.\"],\"other\":[\"A warm, loving family with strong values and a deep sense of community.\",\"We come from a close-knit background where family and faith are central to life.\",\"A well-respected family with a long tradition of education, service and integrity.\",\"Our family is grounded, supportive and deeply values commitment and loyalty.\",\"A diverse and welcoming family. We believe in love, respect and strong character.\",\"We are a family of professionals who believe in hard work, kindness and honesty.\",\"A traditional family with modern values — faith, family and community come first.\",\"Our roots are strong and our values are clear.\",\"A peaceful home built on trust, love and mutual respect.\",\"We come from a background that values education, character and sincere relationships.\"]}', '{\"muslim\":{\"Doctor\":[\"A practising doctor with a passion for helping others. I balance a demanding career with my faith and family values.\",\"Medicine is my calling. I am caring, dedicated and looking for a partner who shares my Islamic values.\",\"Alhamdulillah, I work as a doctor. Outside of work, my deen keeps me grounded. I am serious about marriage.\"],\"Surgeon\":[\"A surgeon who values precision and compassion. Outside the hospital, I enjoy quiet evenings rooted in faith.\",\"My work demands focus. I am looking for a sincere, like-minded partner to build a halal life with.\"],\"Dentist\":[\"A dentist who smiles a lot. I am caring, calm and looking for a sincere partner to build a life together.\",\"Healthcare professional with a love for family life. Faith is my foundation.\"],\"Pharmacist\":[\"A pharmacist by profession, I care about people wellbeing. Looking for a partner with a good heart and strong deen.\",\"I work in healthcare and value a balanced lifestyle spiritually, physically and emotionally.\"],\"Nurse\":[\"A nurse who cares for others daily. Compassion and patience are at the heart of everything I do.\",\"Healthcare is my calling. I bring the same warmth to my personal life as I do to my patients.\"],\"Psychologist\":[\"I help people understand themselves. I am empathetic, calm and deeply rooted in my faith.\",\"A psychologist who believes in building strong, healthy relationships based on Islamic values.\"],\"Software Engineer\":[\"A software engineer who loves solving problems. I am analytical yet deeply family-oriented and grounded in my deen.\",\"I build things for a living and inshAllah a beautiful life with the right person.\",\"Tech professional by day, family-oriented Muslim always. Looking for a sincere partner to complete half my deen.\"],\"Civil Engineer\":[\"A civil engineer with a structured mind and warm heart. I take pride in my work and my Islamic values.\",\"I design structures professionally, and hope to build a strong family foundation with the right partner.\"],\"Mechanical Engineer\":[\"An engineer by profession, grounded in faith and family values. I am serious about finding a life partner.\",\"I solve problems for a living. Looking for a partner who brings peace and deen to my life.\"],\"Lawyer\":[\"A lawyer by profession, I believe in justice, honesty and strong family values rooted in Islam.\",\"I advocate for others professionally. Looking for a life partner who values loyalty, integrity and deen.\"],\"Teacher\":[\"Teaching is my passion. I love sharing knowledge and believe in raising a family with strong moral and Islamic values.\",\"An educator who believes in continuous growth. I am patient, kind and deeply committed to my faith.\",\"I teach the next generation with purpose. I hope to find a partner who values knowledge, faith and family.\"],\"Professor\":[\"An academic who values knowledge, faith and a balanced family life. I am sincere and ready for marriage.\",\"Research and teaching fill my days. Looking for a partner who values intellect and deen equally.\"],\"Accountant\":[\"A careful and responsible accountant. I value stability, honesty and a simple family life built on deen.\",\"Numbers are my profession, but people are my priority. Looking for a sincere partner to build a halal life with.\"],\"Financial Analyst\":[\"A finance professional who values stability and planning in work and in life. Serious about marriage.\",\"I analyse risks for a living. The best decision I can make is choosing the right life partner.\"],\"Entrepreneur\":[\"I run my own business and believe in hard work, vision and barakah. Looking for a supportive partner to grow with.\",\"Building something meaningful drives me every day. I want a partner who shares ambition and love for Allah.\"],\"Manager\":[\"A manager who leads with integrity. I value teamwork, respect and a family life built on Islamic principles.\",\"I manage teams professionally and hope to manage a household with love, laughter and deen.\"],\"Architect\":[\"I design spaces for a living, and hope to design a beautiful halal life with a like-minded partner.\",\"An architect with an eye for detail and a heart full of faith. I value beauty, balance and strong family ties.\"],\"Pilot\":[\"A pilot who sees the world from above. I am grounded in my faith and looking for a partner to come home to.\",\"I travel for work but my heart is rooted in family and deen. Looking for my co-pilot in life.\"],\"Chef\":[\"I express love through food. A chef by passion, looking for a partner to share life meals with.\",\"They say the way to the heart is through food - hoping that works for marriage too!\"],\"default\":[\"I am a sincere, family-oriented individual with strong Islamic values. I take this search seriously.\",\"A practising Muslim with a good heart. I value honesty, respect and building a home filled with deen and love.\",\"Alhamdulillah, I have much to be grateful for. Looking for a sincere partner to complete half my deen.\",\"I am simple, sincere and serious about marriage. My faith and family are my priorities.\",\"A grounded, faith-driven individual looking for a genuine connection and a stable, loving family life.\",\"I believe in the beauty of nikah and the blessing of a righteous home.\",\"Someone who takes their deen seriously but also has a warm heart and a good sense of humour.\"]},\"other\":{\"Doctor\":[\"A dedicated doctor with a passion for healing and a heart full of compassion. Looking for a genuine long-term partner.\",\"Medicine keeps me busy, but family keeps me grounded. Looking for someone who appreciates both.\"],\"Nurse\":[\"A nurse who gives her all for others. I am compassionate, patient and looking for a genuine partner.\",\"Caring for others is my profession. Looking for someone to share life journey with.\"],\"Software Engineer\":[\"A software engineer who enjoys problem-solving at work and meaningful conversations outside of it.\",\"I build technology by day and hope to build a beautiful life with the right person.\"],\"Civil Engineer\":[\"An engineer with a calm mind and a warm heart. Looking for a committed partner to build a future with.\",\"I design things for a living. I hope to design a great life alongside the right person.\"],\"Teacher\":[\"Teaching is my purpose. I believe in growth, kindness and a life filled with learning and love.\",\"An educator with a big heart. I value honesty, commitment and a warm family life.\"],\"Lawyer\":[\"A lawyer who believes in fairness, honesty and strong relationships built on trust.\",\"I argue for a living but I am actually very easy to get along with. Looking for a genuine connection.\"],\"Accountant\":[\"Organised, dependable and down-to-earth. I value stability and a sincere partnership.\",\"Numbers by day, heart-first by nature. Looking for someone real and genuine.\"],\"Entrepreneur\":[\"I built something from scratch and I am proud of it. Looking for a partner who matches my energy and values.\",\"An entrepreneur who believes in creating value in business and in relationships.\"],\"Architect\":[\"I design beautiful spaces. Now I am looking to build a beautiful life with the right person.\",\"Detail-oriented by profession, warm-hearted by nature. Looking for a serious long-term relationship.\"],\"Chef\":[\"Food is my love language. Looking for a partner who appreciates good meals and genuine connection.\",\"I cook for a living and love doing it. Looking for someone to share life table with.\"],\"default\":[\"I am sincere, caring and ready to invest in the right relationship. Looking for a genuine life partner.\",\"Family is everything to me. I am looking for someone kind, committed and ready to build something real.\",\"I believe in honest, meaningful relationships. Ready to find my person.\",\"A warm, grounded individual looking for a serious long-term relationship with the right partner.\",\"Life is better shared. Looking for a genuine, caring partner to build a future with.\"]}}', '{\"muslim\":[\"Open to nikah only\",\"Seeking serious proposals only\",\"Looking for a long-term nikah\",\"Ready for marriage with family involvement\",\"Prefer guardian/wali involvement\",\"Serious about marriage, taking it step by step\",\"Looking for a righteous life partner\",\"Seeking a halal relationship leading to nikah\",\"Ready to meet families when suitable\",\"Open to serious proposals no time-wasters\"],\"other\":[\"Seeking a serious long-term relationship\",\"Looking for marriage-minded partner\",\"Open to engagement first\",\"Ready for commitment\",\"Serious about settling down\",\"Looking for a life partner\",\"Open to meeting families when the time is right\",\"Looking for something genuine and long-term\",\"Ready to build a future together\",\"Serious about finding the right person\"]}', '2026-04-20 20:37:54', '2026-04-21 20:28:52');
